mapper.select:
SELECT id, name, email, password_hash AS passwordHash,
       oauth_provider AS oauthProvider, oauth_provider_id AS oauthProviderId
FROM app_user
WHERE oauth_provider = #{oauthProvider}
  AND oauth_provider_id = #{oauthProviderId}
LIMIT 1

SELECT id, name, email
FROM app_user
WHERE email = #{email}
  AND name = #{name}
LIMIT 1

mapper.update:
